import {revealTime} from './eye-journey.js?v=motion-v70';
export const playbackDefaults={speed:1,reverse:false,delay:0,pauseAt:.5,pauseFor:0,ease:'linear',slowFast:false,slowStart:.3,slowEnd:.65,slowSpeed:.35,fastSpeed:2};
const clamp=x=>Math.max(0,Math.min(1,x));
export function animationClock(elapsed,duration,input={}){const f={...playbackDefaults,...input},length=Math.max(.001,Number(duration)||1),speed=Math.max(.05,Number(f.speed)||1),local=(elapsed-Math.max(0,f.delay))*speed,stop=clamp(f.pauseAt)*length,pause=Math.max(0,f.pauseFor)*speed,after=local<=stop?local:local<stop+pause?stop:local-pause;let q=clamp(after/length);if(f.ease==='smooth')q=q*q*(3-2*q);else if(f.ease==='in')q*=q;else if(f.ease==='out')q=1-(1-q)**2;if(f.slowFast)q=revealTime(q,{historyRevealSlowEnabled:true,historyRevealSlowStart:f.slowStart,historyRevealSlowEnd:f.slowEnd,historyRevealSlowSpeed:f.slowSpeed,historyRevealFastSpeed:f.fastSpeed});if(f.reverse)q=1-q;return {active:elapsed>=Math.max(0,f.delay),time:q*length,progress:q,playingSpan:length/speed+Math.max(0,f.delay)+Math.max(0,f.pauseFor)};}
export function createAnimationInstance(definition,overrides={}){const copy=structuredClone(overrides);return {schema:'regaarder-animation-instance-v1',effectId:definition.id,...copy,playback:{...playbackDefaults,...copy.playback},parameters:{...structuredClone(definition.defaults||{}),...copy.parameters},bindings:{...copy.bindings}};}
export function resolveAnimationParameters(definition,instance){return {...structuredClone(definition.defaults||{}),...structuredClone(instance.parameters||{})};}
